const state={product:'photon100',period:'all',variant:'all',metric:'qualification',view:'conclusions',endpoint:'wait',run:null,wafer:'all',search:'',page:0,sort:'id',asc:true};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const selected=()=>WAFERS.filter(w=>(state.product==='all'||w.product===state.product)&&(state.period==='all'||w.monthIndex===+state.period)&&(state.variant==='all'||w.variant===state.variant));
